import{annotate}from"./rough-notation.js";function annotateOnFocus(t,o){for(const e of["mouseover","focus"])t.addEventListener(e,(()=>{o.show()}));for(const e of["mouseout","blur"])t.addEventListener(e,(()=>{o.hide()}))}const links=document.querySelectorAll("a"),linkAnnotateArray=[];links.forEach(((t,o)=>{linkAnnotateArray.push(annotate(t,{type:"highlight",color:"rgba(253, 166, 166, 0.3)",padding:15})),annotateOnFocus(t,linkAnnotateArray[o])}));const pictures=document.querySelectorAll(".img-box"),captionAnnotateArray=[];pictures.forEach(((t,o)=>{const e=t.querySelector(".caption");window.matchMedia("(prefers-color-scheme: dark)").matches?captionAnnotateArray.push(annotate(e,{type:"bracket",color:"#fff",strokeWidth:4,padding:[10,10],brackets:["left","right"]})):captionAnnotateArray.push(annotate(e,{type:"bracket",color:"#000",strokeWidth:4,padding:[10,10],brackets:["left","right"]})),annotateOnFocus(t,captionAnnotateArray[o])})),document.onkeydown=function(t){27===t.keyCode&&document.querySelector(".modal-toggle:checked + .modal .modal-close").click()},Array.prototype.slice.call(document.querySelectorAll(".modal-toggle")).forEach((function(t){t.addEventListener("change",(function(t){Array.prototype.slice.call(document.querySelectorAll(".modal-toggle:not(#"+t.target.id+")")).forEach((function(t){t.checked=!1})),document.body.className=t.target.checked?"modal-opened":""}))}));